//! curio-desktop — the Tauri head over the curio-core engine.
//!
//! A *thin* head: every `#[tauri::command]` in [`commands`] delegates to
//! `Arc<CoreHandle>` with zero business logic; TS bindings are generated
//! by tauri-specta from [`specta_builder`] (committed at
//! `apps/desktop/src/lib/bindings.ts`, regenerated by `just bindings`,
//! drift-gated by CI's `ipc-contract` job); the security posture lives in
//! `tauri.conf.json` (strict CSP, scoped asset protocol) and
//! `capabilities/main.json` (minimal per-window ACL).
//!
//! Boundary rule: this is the only workspace crate that may depend on
//! tauri. `curio-core` stays webview-free — `deny.toml` wrappers +
//! `cargo run -p xtask -- boundary` enforce it mechanically.

pub mod browser_args;
pub mod commands;
pub mod discovery;
pub mod dto;
pub mod error;
pub mod events;
pub mod image_cache;
pub mod ipc_policy;
pub mod logging;
pub mod menu;
pub mod notify;
pub mod paths;
pub mod refresh_scheduler;
pub mod startup;

use tauri::Manager as _;

/// The tauri-specta builder naming every command and event — the single
/// source of the generated TS bindings AND the runtime invoke handler,
/// so the exported contract cannot drift from what actually runs.
///
/// The bigint cast is deliberate: IDs are `SQLite` rowids and counts are
/// row counts — far inside JS's safe-integer range — so `i64`/`u64`
/// export as `number` instead of failing the export.
#[must_use]
pub fn specta_builder() -> tauri_specta::Builder<tauri::Wry> {
    tauri_specta::Builder::<tauri::Wry>::new()
        .dangerously_cast_bigints_to_number()
        .commands(tauri_specta::collect_commands![
            // feeds
            commands::feeds::discover_feeds,
            commands::feeds::add_feed,
            commands::feeds::remove_feed,
            commands::feeds::list_feeds,
            commands::feeds::get_feed,
            commands::feeds::get_feed_by_url,
            commands::feeds::set_feed_status,
            commands::feeds::update_feed_metadata,
            commands::feeds::set_feed_tags,
            commands::feeds::set_feed_title,
            commands::feeds::set_feed_metadata,
            commands::feeds::set_feed_full_text,
            commands::feeds::reorder_feeds,
            commands::feeds::refresh_feed,
            commands::feeds::refresh_all,
            commands::feeds::recent_fetches,
            // articles
            commands::articles::list_articles,
            commands::articles::get_article,
            commands::articles::load_full_article,
            commands::articles::save_url,
            commands::articles::get_article_state,
            commands::articles::get_article_tags,
            commands::articles::get_unread_counts,
            commands::articles::count_articles,
            commands::articles::delete_article,
            commands::articles::search_articles,
            // read-state / stars / read-later
            commands::state::mark_read,
            commands::state::mark_all_read,
            commands::state::record_opened,
            commands::state::set_archived,
            commands::state::set_starred,
            commands::state::set_read_later,
            // tags
            commands::tags::tag_article,
            commands::tags::untag_article,
            commands::tags::list_tags,
            // destinations / promote
            commands::destinations::add_destination,
            commands::destinations::list_destinations,
            commands::destinations::remove_destination,
            commands::destinations::promote_article,
            commands::destinations::promote_all,
            // opml
            commands::opml::import_opml,
            commands::opml::import_file,
            commands::opml::export_opml,
            // theme yaml io
            commands::theme::export_text_file,
            commands::theme::read_text_file,
            // reddit API credentials (D15; secret is write-only)
            commands::reddit::set_reddit_api,
            commands::reddit::clear_reddit_api,
            commands::reddit::get_reddit_api_status,
            // settings / app
            commands::settings::get_setting,
            commands::settings::set_setting,
            commands::settings::get_app_info,
            // notifications
            notify::request_notification_permission,
            // health / doctor
            commands::health::integrity_check,
            commands::health::fts_integrity_check,
            commands::health::vacuum_db,
            commands::health::db_stats,
            commands::health::sweep_event_retention,
            commands::health::legacy_profiles,
            // platform
            commands::platform::get_cached_image,
            commands::platform::copy_diagnostics_bundle,
            commands::platform::pick_import_file,
            commands::platform::pick_export_path,
            commands::platform::pick_theme_export_path,
            commands::platform::pick_theme_import_file,
            commands::platform::pick_destination_root,
            // startup recovery (work without a core)
            commands::recovery::get_startup_failure,
            commands::recovery::retry_startup,
            commands::recovery::restore_startup_backup,
            commands::recovery::start_fresh_profile,
            commands::recovery::reveal_profile_folder,
            commands::recovery::quit_app,
        ])
        .events(tauri_specta::collect_events![
            events::FeedsChanged,
            events::ArticlesChanged,
            events::RefreshProgress,
            events::RefreshFinished,
            events::MenuAction,
        ])
}

/// Builds and runs the app: plugins (single-instance first, dialog,
/// URL-scoped opener — deliberately NO shell plugin), the specta invoke
/// handler, and managed state (core handle, path registry, image cache).
///
/// Startup is two-phase ([`startup`]): a profile that will not open is
/// logged and shown on the in-window recovery screen, never a silent
/// `exit(1)`.
pub fn run() {
    let builder = specta_builder();

    let tauri_builder = tauri::Builder::default()
        .plugin(tauri_plugin_single_instance::init(|app, _argv, _cwd| {
            // A second launch focuses the existing window instead.
            if let Some(window) = app.get_webview_window(MAIN_WINDOW) {
                let _ = window.set_focus();
            }
        }))
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_process::init())
        .plugin(tauri_plugin_updater::Builder::new().build())
        .invoke_handler(builder.invoke_handler())
        .menu(menu::build)
        .on_menu_event(menu::on_event)
        .setup(move |app| {
            builder.mount_events(app);
            // Managed before the window exists: the frontend's first call
            // asks the gate whether to show the reader or the recovery screen.
            app.manage(startup::StartupGate::default());
            // Before the profile is touched, so the window exists whatever
            // happens next (tauri itself would have built a `create: true`
            // window slightly earlier, ahead of its asset setup and this
            // closure — nothing here depends on that). A window that cannot
            // be built leaves nothing to show a recovery screen in: that one
            // failure still ends the process.
            create_main_window(app).inspect_err(|error| {
                tracing::error!("could not create the main window: {error}");
            })?;

            // The one-time move of a pre-0.5 profile (the old CLI location,
            // or Roaming `AppData` on Windows) onto the default shared with the
            // CLI — before logging, which would create the default dir. A
            // library it cannot move yet is opened where it is, never
            // stranded behind a fresh empty default. No home directory at
            // all goes to the recovery screen below.
            let profile = paths::profile_dir().map(|default| {
                let paths::StartupProfile {
                    dir,
                    outcomes,
                    legacy,
                } = paths::startup_profile(
                    default,
                    &curio_core::paths::legacy_profile_dirs(),
                    curio_core::paths::legacy_desktop_profile_dir().as_deref(),
                );
                // Rotating logs + panic hook first, so anything below is
                // captured (including why the profile would not open).
                logging::init(&dir.join("logs"));
                for notice in &outcomes {
                    tracing::warn!(%notice, "legacy profile");
                }
                (dir, legacy)
            });
            // Served to the startup notice and the doctor panel.
            let profile = match profile {
                Ok((dir, legacy)) => {
                    app.manage(legacy);
                    Ok(dir)
                }
                Err(error) => {
                    app.manage(paths::LegacyProfiles::default());
                    Err(error)
                }
            };
            app.manage(ipc_policy::PathRegistry::new());

            // Phase 1 (open) then phase 2 (install); a failure at either goes
            // to the recovery screen, already logged.
            if let Err(failure) =
                startup::boot(profile).and_then(|core| startup::install(app.handle(), core))
            {
                app.state::<startup::StartupGate>().record(failure)?;
            }
            Ok(())
        });

    if let Err(error) = tauri_builder.run(tauri::generate_context!()) {
        // The runtime itself failed (no webview, no window): there is no
        // surface to show a recovery screen on. Log it for the diagnostics
        // bundle, and keep stderr for development.
        tracing::error!("curio-desktop failed to start: {error}");
        eprintln!("curio-desktop failed to start: {error}");
        std::process::exit(1);
    }
}

/// The label of the one window, configured in `tauri.conf.json`.
const MAIN_WINDOW: &str = "main";

/// Builds the main window from its `tauri.conf.json` entry. That entry is
/// `create: false` so the window is made here, where a debug build on
/// Windows can hand `WebView2` the automation flags wry would otherwise
/// shadow (see [`browser_args`]).
fn create_main_window(app: &tauri::App) -> Result<(), Box<dyn std::error::Error>> {
    let config = app
        .config()
        .app
        .windows
        .iter()
        .find(|window| window.label == MAIN_WINDOW)
        .ok_or("tauri.conf.json has no `main` window")?;
    let window = tauri::WebviewWindowBuilder::from_config(app.handle(), config)?;
    #[cfg(all(windows, debug_assertions))]
    let window = match browser_args::with_injected(
        std::env::var(browser_args::AUTOMATION_ENV).ok().as_deref(),
    ) {
        Some(args) => window.additional_browser_args(&args),
        None => window,
    };
    window.build()?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::MAIN_WINDOW;

    /// `create_main_window` is the only place the main window is made: tauri
    /// must not also create it from the config (a second window with the
    /// same label fails startup), and the entry it builds from must exist.
    #[test]
    fn the_config_leaves_main_window_creation_to_setup() {
        let config: serde_json::Value =
            serde_json::from_str(include_str!("../tauri.conf.json")).unwrap_or_default();
        let windows = config["app"]["windows"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        let main: Vec<_> = windows
            .iter()
            .filter(|window| window["label"] == MAIN_WINDOW)
            .collect();
        assert_eq!(main.len(), 1, "exactly one `{MAIN_WINDOW}` window");
        assert!(
            windows.iter().all(|window| window["create"] == false),
            "every configured window is `create: false`, made in setup"
        );
    }
}
